const{execSync:execSync}=require("child_process"),path=require("path"),fs=require("fs"),MIGRATION_ROOT=__dirname,steps=[{name:"1. Şube Migrasyonu (migrate_tenants.js)",command:"node migrate_tenants.js",description:"MSSQL SUBE verilerini sys_tenants tablosuna aktarır."},{name:"2. MySQL Şema Hazırlığı (prepare_mysql_schema.js)",command:"node migration/prepare_mysql_schema.js",description:"Legacy sütunları (legacy_id, legacy_visit_id) hazırlar."},{name:"3. MSSQL Veri Çıkarma (extract_mssql.js)",command:"node migration/extract_mssql.js",description:"MSSQL verilerini okur ve json dosyasına kaydeder."},{name:"4. MySQL Veri Yükleme (load_mysql.js)",command:"node migration/load_mysql.js",description:"JSON verilerini MySQL veritabanına yükler."},{name:"5. Branş Verileri Birleştirme (merge_specialty_data.js)",command:"node merge_specialty_data.js",description:"Laboratuvar ve Radyoloji metinlerini birleştirir, muayene notlarını aktarır."},{name:"6. Uzmanlık Kategorizasyonu (categorize_specialty.js)",command:"node categorize_specialty.js",description:"Muayene kayıtlarını branş kodlarına göre işaretler."},{name:"7. Laboratuvar Metadata (migrate_lab_metadata.js)",command:"node migrate_lab_metadata.js",description:"Laboratuvar test tanımlarını ve referans aralıklarını aktarır."},{name:"8. Laboratuvar Sonuçları (migrate_lab_data.js)",command:"node migrate_lab_data.js",description:"Detaylı laboratuvar sonuçlarını aktarır."},{name:"9. Dosya Migrasyonu (migrate_files.js)",command:"node migrate_files.js",description:"Hasta dosyalarını ve radyoloji raporlarını aktarır."},{name:"10. Ödeme Migrasyonu (migrate_payments.js)",command:"node migrate_payments.js",description:"Finansal kayıtları ve ödemeleri aktarır. (batch: 500)"},{name:"11. Blind Index Migrasyonu (migrate_blind_index.php)",command:"DB_HOST=127.0.0.1 DB_NAME=test_klinik /opt/lampp/bin/php migrate_blind_index.php",description:"Şifreli hasta verileri için arama endekslerini oluşturur."},{name:"12. Legacy Table Mapping (seed_legacy_table_map.js)",command:"node migration/seed_legacy_table_map.js",description:"Legacy tablo eşleşmelerini (map_legacy_tables) oluşturur."},{name:"13. Activity Logs Migrasyonu (migrate_activity_logs.js)",command:"node migrate_activity_logs.js",description:"GENELLOG ve LOG_KAYITDEGISIKLIGI kayıtlarını cln_activity_logs tablosuna aktarır."},{name:"14. Data Access Logs Migrasyonu (migrate_data_access_logs.js)",command:"node migrate_data_access_logs.js",description:"Kullanici_Log_KayitErisim kayıtlarını cln_data_access_logs tablosuna aktarır."},{name:"15. Consent Logs Migrasyonu (migrate_consent_logs.js)",command:"node migrate_consent_logs.js",description:"Gizlilik onam loglarını ptn_consent_logs tablosuna aktarır."},{name:"16. Message Logs Migrasyonu (migrate_message_logs.js)",command:"node migrate_message_logs.js",description:"SMS ve Email loglarını sys_sms_logs ve sys_email_logs tablolarına aktarır."}];for(let a=0;a<steps.length;a++){const e=steps[a];try{execSync(e.command,{stdio:"inherit",cwd:MIGRATION_ROOT,timeout:36e5})}catch(a){a.signal,a.stderr,process.exit(1)}}